    left = size - len(chosen)
    while left and any(quota[path] < len(group[path]) for path in files):
        for path in files:
            if left and quota[path] < len(group[path]):
                quota[path] += 1
                left -= 1
    for path in files:
        rows, take = group[path], quota[path]
        for i in range(take):
            chosen.append({"file": path, **rows[(2 * i + 1) * len(rows) // (2 * take)]})
return chosen
